class Solution {
    public int lastSnowball(int[] weights) {
        // Smash two heaviest each turn, so keep snowballs in max-heap
        // Unequal pair leaves difference, which goes back in
        // reverseOrder makes poll() return heaviest
        PriorityQueue<Integer> pq = new PriorityQueue<>(Collections.reverseOrder());
        for (int w : weights) pq.add(w);
        while (pq.size() > 1) {
            int heaviest = pq.poll(), second = pq.poll();
            // unequal, so lighter vanishes and heavier shrinks; equal pair both vanish
            if (heaviest != second) pq.add(heaviest - second);
        }
        // empty heap = everything destroyed
        return pq.isEmpty() ? 0 : pq.peek();
    }
}

