class Solution {
    public int[][] mergeBookings(int[][] bookings) {
        // Sort by start, so booking can only touch last block
        // Booking either stretches last block or starts new one
        // copy, so sort leaves input order alone
        int[][] ordered = bookings.clone();
        // by start, ties by end (compare, not subtract, avoiding overflow)
        Arrays.sort(ordered, (x, y) -> x[0] != y[0] ? Integer.compare(x[0], y[0]) : Integer.compare(x[1], y[1]));
        List<int[]> out = new ArrayList<>();
        for (int[] booking : ordered) {
            // overlaps or touches last block, so stretch it
            if (!out.isEmpty() && booking[0] <= out.get(out.size() - 1)[1]) {
                int[] last = out.get(out.size() - 1);
                // max keeps block end when booking sits inside it
                last[1] = Math.max(last[1], booking[1]);
            } else {
                // gap, so new block (new array, ensuring input rows stay untouched)
                out.add(new int[] {booking[0], booking[1]});
            }
        }
        return out.toArray(new int[0][]);
    }
}

