class Solution {
    public int[][] mergeBookings(int[][] bookings) {
        // Turn bookings into start and end events, swept in time order
        // Depth = bookings active; block runs from depth 0 up and back to 0
        int n = bookings.length;
        // event = time * 2 + kind (0 = start, 1 = end); long, since time * 2 can overflow int
        long[] events = new long[2 * n];
        for (int i = 0; i < n; i++) {
            events[2 * i] = (long) bookings[i][0] * 2;
            events[2 * i + 1] = (long) bookings[i][1] * 2 + 1;
        }
        // time then kind, so start comes before end on ties and touching bookings merge
        Arrays.sort(events);
        List<int[]> out = new ArrayList<>();
        // depth (bookings active now)
        int depth = 0, blockStart = 0;
        // events in time order
        for (long event : events) {
            // undo time * 2 + kind
            int t = (int) (event / 2);
            // start event
            if (event % 2 == 0) {
                // nothing active, so new block opens here
                if (depth == 0) blockStart = t;
                depth++;
            } else if (--depth == 0) {
                // end event emptied depth, so block closes
                out.add(new int[] {blockStart, t});
            }
        }
        return out.toArray(new int[0][]);
    }
}

