class Solution {
    public int[][] mergeBookings(int[][] bookings) {
        // Sort by start, so booking can only touch last block
        // Last block's end decides if booking stretches it or starts new block
        int n = bookings.length;
        // copy, so sort leaves input order alone
        int[][] ordered = new int[n][];
        for (int i = 0; i < n; i++) {
            ordered[i] = new int[]{bookings[i][0], bookings[i][1]};
        }
        Arrays.sort(ordered, (x, y) -> Integer.compare(x[0], y[0]));
        List<int[]> merged = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int start = ordered[i][0];
            int end = ordered[i][1];
            // null = no block yet
            int[] last = null;
            if (merged.size() > 0) {
                last = merged.get(merged.size() - 1);
            }
            // starts within last block (touching counts)
            if (last != null && start <= last[1]) {
                // sticks out past block end, so stretch
                if (end > last[1]) {
                    last[1] = end;
                }
            } else {
                // gap, so new block
                merged.add(new int[]{start, end});
            }
        }
        // list rows into 2D array
        int[][] result = new int[merged.size()][];
        for (int i = 0; i < merged.size(); i++) {
            result[i] = merged.get(i);
        }
        return result;
    }
}

