class Solution {
    public int minTime(int[][] grid) {
        // Reachable(t) = corner connects to start through cells at most t
        // Reachable only gets easier as t grows, so binary search smallest t
        // Test each t with BFS flood fill from start
        // answer between start elevation and n*n - 1 (every cell covered)
        int n = grid.length, lo = grid[0][0], hi = n * n - 1;
        while (lo < hi) {
            // middle, rounded down
            int mid = (lo + hi) / 2;
            // reachable, so mid could be answer (hi = mid, not mid - 1)
            if (ok(grid, mid)) hi = mid;
            // cut off at mid, so answer is later
            else lo = mid + 1;
        }
        return lo;
    }
    // BFS over cells water covers at time t
    private boolean ok(int[][] g, int t) {
        int n = g.length;
        // start itself must be covered
        if (g[0][0] > t) return false;
        boolean[][] seen = new boolean[n][n];
        ArrayDeque<int[]> q = new ArrayDeque<>();
        q.add(new int[] {0, 0});
        seen[0][0] = true;
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            // corner reached
            if (cur[0] == n - 1 && cur[1] == n - 1) return true;
            // four neighbours of cell
            for (int[] d : dirs) {
                int nr = cur[0] + d[0], nc = cur[1] + d[1];
                // flood into covered neighbour, mark on push ensuring no repeats
                if (nr >= 0 && nr < n && nc >= 0 && nc < n && !seen[nr][nc] && g[nr][nc] <= t) {
                    seen[nr][nc] = true;
                    q.add(new int[] {nr, nc});
                }
            }
        }
        // queue drained, corner cut off
        return false;
    }
}

