class Solution {
    public int minTime(int[][] grid) {
        // Time on path = highest cell on it (water must reach every cell)
        // Smallest time pops first, so first pop of cell is its best
        int n = grid.length;
        boolean[][] seen = new boolean[n][n];
        // entries {time, row, col}, smallest time first
        PriorityQueue<int[]> heap = new PriorityQueue<>((x, y) -> Integer.compare(x[0], y[0]));
        // start cell opens at its own elevation
        heap.add(new int[]{grid[0][0], 0, 0});
        int[] rowSteps = {1, -1, 0, 0};
        int[] colSteps = {0, 0, 1, -1};
        while (!heap.isEmpty()) {
            int[] entry = heap.poll();
            int time = entry[0];
            int r = entry[1];
            int c = entry[2];
            // stale duplicate, cell already finalised
            if (seen[r][c]) {
                continue;
            }
            // first pop of corner, so time is minimum
            if (r == n - 1 && c == n - 1) {
                return time;
            }
            // mark on pop, so later duplicates are skipped
            seen[r][c] = true;
            // four neighbours of cell
            for (int d = 0; d < 4; d++) {
                int nr = r + rowSteps[d];
                int nc = c + colSteps[d];
                boolean inside = nr >= 0 && nr < n && nc >= 0 && nc < n;
                if (inside && !seen[nr][nc]) {
                    // water must cover neighbour too, so max(time, its elevation)
                    int arrive = time;
                    if (grid[nr][nc] > arrive) {
                        arrive = grid[nr][nc];
                    }
                    heap.add(new int[]{arrive, nr, nc});
                }
            }
        }
        return -1;  // unreachable
    }
}

